export const EVENT_CATEGORY_LABELS: Record<EventCategory, string> = {
  Cultural: "Cultural & Festivals",
  Sports: "Sports",
  IndustrialVisit: "Industrial Visits",
  Placement: "Placement Drives",
  Lab: "Labs & Workshops",
  CareerProgram: "Career & Training",
  Convocation: "Convocation & Achievements",
  Other: "Other",
};

// Placement removed from the Events gallery order — placement drives
// live on /placements and shouldn't double-up in the events gallery.
// Photos tagged "Placement" stay in the catalog (no data loss) but are
// hidden from category cards + filters here.
export const EVENT_CATEGORY_ORDER: EventCategory[] = [
  "Cultural",
  "Sports",
  "Lab",
  "IndustrialVisit",
  "CareerProgram",
  "Convocation",
  "Other",
];

/** Years present in the catalog, newest first. */
export const EVENT_YEARS: number[] = Array.from(
  new Set(EVENT_PHOTOS.map((p) => p.year).filter((y): y is number => y !== null)),
).sort((a, b) => b - a);
